R=Path('.development-artifacts/cpd-anti-gpu-cube-context-v5');A=R.parent

def finalize():
 comparison=read(R/'replicate_comparison_v17.json');rows=comparison['results'];assert len(rows)==6
 paths=[('anti',1,'aggregate_native_audit_v8.json'),('control',1,'native_audit_v9.json'),('anti',2,'aggregate_native_audit_v12.json'),('control',2,'aggregate_native_audit_v14.json'),('anti',3,'aggregate_native_audit_v16.json'),('control',3,'native_audit_v17.json')]
 audits=[]
 for c,r,n in paths:
  p=R/c/f'replica-{r}/validation'/n;a=read(p);assert a['passed'];audits.append(dict(case=c,replica=r,audit=source(p),late5ns=a['late5ns_physical'],scope=a['scope']))
 pairs=[]
 for rep in [1,2,3]:
  anti=next(v for v in rows if v['case']=='anti' and v['replica']==rep);control=next(v for v in rows if v['case']=='control' and v['replica']==rep)
