 fit=A/'cpd-anti-readiness-fit-state-v3';selected=read(checked(read(fit/'conformational_candidate_lock.json')['candidate_assessment']))
 points=read(fit/'points.json');by_id={r['case_id']:r for r in selected['results']}
 cross=[dict(case_id=p['case_id'],inherited_source_constrained_field=p.get('constrained'),branch=p['branch'],actual_MM_constraint_applied=by_id[p['case_id']]['constraint_applied'],interpretation='Source QM metadata is not the MM constraint schedule; v3 MM constrains measured glycosidic torsion except remote-unconstrained branch.') for p in points]
 assert all(v['actual_MM_constraint_applied']==(v['branch']!='remote-unconstrained') for v in cross)
 sources=[fit/'receipt.json',fit/'lineage.json',fit/'points.json',fit/'conformational_candidate_lock.json',A/'cpd-anti-readiness-fit-v3-r1/worker.py',A/'cpd-anti-readiness-fit-v3-r1/started.json',A/'cpd-anti-readiness-fit-v3-r1/model-048/assessment.json',A/'cpd-anti-readiness-fit-v3-r1/native_audit.json',Path('experiments/cpd_anti_additive/audit_readiness_fit_v3.py')]
 errata=dict(at=now(),append_only=True,original_records_unchanged=True,corrections=[dict(field='receipt.optimizer name/method',inherited='scipy.optimize.least_squares / trf',actual='v3 gate-directed finite-difference sensitivities and scipy.optimize.minimize(method=SLSQP) epigraph/minimax proposals,then nonlinear Sella/MM evaluation;22 bounded coefficients. Not a least_squares/trf fit.'),dict(field='receipt.at',inherited=read(fit/'receipt.json')['at'],actual_fit_started_at=read(A/'cpd-anti-readiness-fit-v3-r1/started.json')['at'],interpretation='Inherited receipt date is historical input provenance,not v3 execution timestamp.'),dict(field='points.constrained',interpretation='Do not infer executed MM constraint from inherited source-QM field; use per-case crosswalk and native result constraint_applied. Representatives are unconstrained; stationarity and directional curvature do not certify all-mode minima.'),dict(field='assembly.actual_equilibrated_concentration_pending',interpretation='Historical pre-run flag remains unchanged; six audited late5ns actual addedNaCl concentrations now available in campaign review. Excludes93 neutralizing sodium; not total ionic strength.'),dict(field='earlier validation passes',interpretation='Old image-clearance and negative-pressure/cavity failures remain failed; fixed-box or earlier small/long-box trajectories receive zero credit toward final60ns. Force-switch,NPT,cubicbox,saltcount and geometry storage handling changes are disclosed in campaign history,not retrospective old-policy passes.')],constraint_crosswalk=cross,inputs=[source(p) for p in sources],minimum_certified=False,simulation_ready=False)
 save(R/'provenance_errata_v17.json',errata)
 report=dict(at=now(),registered_runs=6,completed_validation_ns=60,unique_saved_frames=6000,all_six_native_and_finite_context_audits_passed=True,scope='Existing additive cis-anti-I interstrand TT context,three anti andthree matched undamaged10ns runs. Worker checks all saved frames; independent replay scope varies by replica and is recorded,not falsely all-frame.',audits=audits,comparison=source(R/'replicate_comparison_v17.json'),pairs=pairs,structural_interpretation='Matched mean shared28contact differences anti-control are approximately-0.305,+0.071,+0.019. Sign varies by replicate; initial prepared fractions differ. Anti1 lower retention persists; anti2/anti3 overlap much of control range. Control3 declines fromfirst5ns0.794 tolast5ns0.749. These finite correlated windows do not establish equilibrium,causal lesion effect,mechanics or transferability. Preserve all outcomes; do not choose favorable replicas or refit from these exposed trajectories.',physical_interpretation='Fresh large-cube force-switch NPT removes the observed earlier gross cavity/pressure failure within sampled evidence; recorded temperature,density,pressure,salt and image/void checks support finite-context numerical/chemical qualification only. No posthoc pressure/density acceptance threshold or universal equilibrium claim.',decision='Authorized six-replica preliminary validation endpoint reached. Package all six endpoints for reproducible research restart with limitations. No additional MD automatically justified; no long production launched and no force-field registry or app capability promotion.',future_work='A specific scientific question and separately specified design are needed before extending trajectories or claiming mechanics/transferability. Minimum certification requires its own full-mode evidence; optimizer/MD completion is insufficient.',failures_preserved=['Historical small/long-box image and physical-solvent failures','Anti2 native bad_any_cast startup; cause unresolved despite successful bounded recovery','User-paused segments and discarded uncheckpointed tails; no duplicate credit'],provenance_errata=source(R/'provenance_errata_v17.json'),restart_package_pending=True,full_production_ready=False,simulation_ready=False,minimum_certified=False,equilibrium_certified=False,no_cloud_spending=True)
 save(R/'campaign_review_v17.json',report)
 base=R/'control/replica-3/validation';assert not (base/'completion_review.json').exists()
 save(base/'completion_review.json',dict(at=now(),approved_for_next_run=False,reason='All six registered validations complete; final review/package only,no further simulation automatically admitted',assessment=source(base/'assessment.json'),audit=source(base/'native_audit_v17.json'),performance_report=source(base/'performance_report.json'),campaign_review=source(R/'campaign_review_v17.json'),simulation_ready=False,minimum_certified=False))
 for name in ['finalize_campaign_v17.py','compare_replicas_v17.py']:shutil.copy2(Path('experiments/cpd_anti_additive')/name,R/name)
 print(pairs)
